-- Demo seed: one care home org, one site, two areas, six roles, ~15 staff,
-- a few templates, and a couple of shifts so the dashboard has data to show.


   '00000000-0000-0000-0000-000000000001',
   'Willow Grove — Main House',
   'Europe/London', '21:00', '07:00');


-- Demo admin — auth_user_id left null until first login links it
   '00000000-0000-0000-0000-000000000001',
   'Demo Admin', 'admin@willowgrove.example', 'org_admin');



-- Everyone can Carer; a few can Senior; one Nurse; a couple in Kitchen/Housekeeping/Activities
select s.id, '00000000-0000-0000-0000-000000000100'::uuid from staff s where s.org_id = '00000000-0000-0000-0000-000000000001';


-- Assign some staff to areas

-- Weekday templates: 3 carers day + 2 evening + 1 senior + 1 nurse (ground floor)

-- Coverage: at least 3 carers during the day, every day
select '00000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000100', d, '07:00','15:00', 3, 'Day-shift ratio'
  from generate_series(0,6) d;

-- One shift for today: filled. One shift for tomorrow: open.
   '00000000-0000-0000-0000-000000000010',
   '00000000-0000-0000-0000-000000000100',
   '00000000-0000-0000-0000-000000000020',
   current_date, '07:00','15:00','filled',
   '00000000-0000-0000-0000-000000000201', now() - interval '2 hours');

   '00000000-0000-0000-0000-000000000010',
   '00000000-0000-0000-0000-000000000100',
   '00000000-0000-0000-0000-000000000021',
   current_date + 1, '15:00','22:00','open');
